import{_ as l,C as e,o as p,c as o,E as t,a2 as s}from"./chunks/framework.BOeh4kYD.js";const n="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/01-policy-roles.png",h="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/02-policy-targets.png",d="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/03-agent-industry.png",c="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/04-verifiable-behavior.png",g="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/05-software-value-chain.png",u="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/06-enterprise-paths.png",b="/joinwell52/assets/figures/miit-209-ai-software-policy/zh/07-transformation-roadmap.png",x=JSON.parse('{"title":"工信部209号文深度解读：智能体软件与软件产业转型","description":"","frontmatter":{"title":"工信部209号文深度解读：智能体软件与软件产业转型","date":"2026-09-15","language":"zh-CN","article_type":"policy-analysis","summary":"工信部《“人工智能+软件”专项行动实施方案》不只是推动企业使用AI，而是同时改造软件生产方式、重定义软件产品、培育智能体软件与Skills市场，并启动运行框架、接口标准、行为校验和安全治理等基础建设。","publication_authorized":true,"lifecycle":"Published","column":"industry-architecture","category":"daily","edition":"research-center","cover":"/assets/covers/miit-209-ai-software-policy.png"},"headers":[],"relativePath":"zh/industry/2026-09-15-miit-209-ai-software-policy.md","filePath":"zh/industry/2026-09-15-miit-209-ai-software-policy.md","lastUpdated":1789534935000}'),f={name:"zh/industry/2026-09-15-miit-209-ai-software-policy.md"};function m(q,a,k,_,w,A){const r=e("ArticleCover"),i=e("ArticleTableScroll");return p(),o("div",null,[t(r,{image:"/assets/covers/miit-209-ai-software-policy.png",kicker:"行业架构 · 政策解读",title:"工信部209号文深度解读：智能体软件与软件产业转型",summary:"工信部《“人工智能+软件”专项行动实施方案》不只是推动企业使用AI，而是同时改造软件生产方式、重定义软件产品、培育智能体软件与Skills市场，并启动运行框架、接口标准、行为校验和安全治理等基础建设。",version:"2026-09-15",languageHref:"/en/industry/2026-09-15-miit-209-ai-software-policy",languageLabel:"English"}),t(i,{language:"zh"}),a[0]||(a[0]=s('<h1 id="工信部209号文深度解读-智能体软件与软件产业转型" tabindex="-1">工信部209号文深度解读：智能体软件与软件产业转型 <a class="header-anchor" href="#工信部209号文深度解读-智能体软件与软件产业转型" aria-label="Permalink to &quot;工信部209号文深度解读：智能体软件与软件产业转型&quot;">​</a></h1><p>2026年9月11日，工业和信息化部发布<a href="https://www.miit.gov.cn/jgsj/xxjsfzs/wjfb/art/2026/art_91a26793271e4c77aca49ecde4472999.html" target="_blank" rel="noreferrer">《“人工智能+软件”专项行动实施方案》</a>，文号为工信部信发〔2026〕209号，成文日期为9月2日。文件由工信部印发，面向各省、自治区、直辖市及新疆生产建设兵团工业和信息化主管部门，要求各地结合实际抓好贯彻落实。</p><p>如果只看标题，人们很容易把它理解成“鼓励软件公司多用人工智能”。但读完8页正文和19项任务会发现，它真正讨论的远不止AI辅助写代码。</p><p>这份文件同时触及了软件产业的三个根本问题：</p><p>第一，软件以后怎样被生产；</p><p>第二，软件本身将变成什么；</p><p>第三，当软件开始以智能体的方式持续行动，谁来提供运行框架、技能、市场、标准、安全与责任边界。</p><p>因此，209号文的重要性并不只在于增加了一项“人工智能+”政策，而在于国家开始把<strong>智能编程、智能体软件、智能服务</strong>作为软件产业的新增长极进行系统部署。过去常被混在大模型、聊天机器人、自动化工具里的Agent，现在被放进了一条完整的软件产业链中：有开发工具，有运行框架，有软件产品，有技能包，有应用市场，有交付服务，也有身份、接口、行为和安全标准。</p><p>这意味着，智能体正在从一个模型功能，走向一种独立的软件形态。</p><aside class="policy-keywords" aria-label="六个词读懂209号文"><p class="policy-keywords-title"><strong>读懂209号文，只看这6个词</strong></p><div class="policy-keywords-grid"><div><strong>智能编程</strong><span>变革软件生产</span></div><div><strong>智能伙伴</strong><span>升级已有软件</span></div><div><strong>智能体软件</strong><span>培育新型产品</span></div><div><strong>Skills</strong><span>沉淀专业能力</span></div><div><strong>智能服务</strong><span>持续交付价值</span></div><div><strong>行为可校验</strong><span>检查执行与结果</span></div></div></aside><h2 id="一、这不是414号文的重复-而是补上了-产品与基础设施-这一层" tabindex="-1">一、这不是414号文的重复，而是补上了“产品与基础设施”这一层 <a class="header-anchor" href="#一、这不是414号文的重复-而是补上了-产品与基础设施-这一层" aria-label="Permalink to &quot;一、这不是414号文的重复，而是补上了“产品与基础设施”这一层&quot;">​</a></h2><p>要理解209号文，必须把它放到2026年连续发布的政策序列中，但不能把几份文件混为一谈。</p><p>8月31日发布的<a href="https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_331b6f1d28ad410aa9df711acf42dbfe.html" target="_blank" rel="noreferrer">工信厅科函〔2026〕414号文</a>，围绕人工智能应用服务商建立资源池、服务团、真实场景、交付体系和持续评估机制。它回答的是：<strong>谁把AI送进企业，谁负责咨询、实施、运营与安全治理。</strong></p><p>9月4日发布的<a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">《人工智能中小企业创业支持计划（2026—2028年）》</a>，把智能原生企业、智能体开发者、开源贡献者、“一人公司”和超级个体纳入创业支持视野。它回答的是：<strong>谁来创办新的AI企业，创业所需的算力、数据、场景、资本和服务如何形成。</strong></p><p>这两份文件，我们此前已经分别在<a href="https://joinwell52-ai.github.io/joinwell52/zh/industry/2026-09-04-miit-414-ai-application-delivery" target="_blank" rel="noreferrer">《工信部414号文深度解读：从模型供给走向应用交付》</a>和<a href="https://joinwell52-ai.github.io/joinwell52/zh/industry/2026-09-08-miit-ai-sme-support-plan" target="_blank" rel="noreferrer">《工信部〈人工智能中小企业创业支持计划〉深度解读：AI创业生态正在形成》</a>中作过分析。</p><p>209号文解决的是第三个问题：</p><blockquote><p>这些创业者和服务商，未来究竟要生产、运行和交付怎样的软件？</p></blockquote><p>它把政策重心进一步推进到软件产业内部，从生产工具、技术底座、产品形态、服务模式，到开源、算力、数据、标准、人才和安全，给出了一张更完整的产业施工图。</p><p>三份文件由此形成清晰分工：</p><table tabindex="0"><thead><tr><th>文件</th><th>核心对象</th><th>主要回答的问题</th></tr></thead><tbody><tr><td>414号文</td><td>人工智能应用服务商</td><td>谁来完成咨询、集成、交付、运营和治理</td></tr><tr><td>创业支持计划</td><td>AI中小企业与创业主体</td><td>谁来创业，如何获得算力、数据、场景和资本</td></tr><tr><td>209号文</td><td>软件和信息技术服务业</td><td>下一代软件怎样生产、以什么形态运行、需要什么产业基础</td></tr></tbody></table><p>如果说414号文是在组织“施工队”，创业支持计划是在培育“新企业”，那么209号文是在定义今后要建设的“软件产业新体系”。</p><p><img src="'+n+'" alt="图 1｜三份政策分别组织交付主体、创业生态与软件产业体系，侧重不同、相互补充。"></p><p><em>图 1：三份政策分别组织交付主体、创业生态与软件产业体系，侧重不同、相互补充。 来源：工信部相关政策文件，作者整理。</em></p><h2 id="二、为什么叫-人工智能-软件-而不是简单的-软件-ai" tabindex="-1">二、为什么叫“人工智能+软件”，而不是简单的“软件+AI” <a class="header-anchor" href="#二、为什么叫-人工智能-软件-而不是简单的-软件-ai" aria-label="Permalink to &quot;二、为什么叫“人工智能+软件”，而不是简单的“软件+AI”&quot;">​</a></h2><p>文件开头使用了三个非常准确的词：人工智能正在改变软件业的<strong>开发方式、产品形态与服务模式</strong>。</p><p>这三者分别对应三场变化。</p><h3 id="第一场变化-软件生产方式改变" tabindex="-1">第一场变化：软件生产方式改变 <a class="header-anchor" href="#第一场变化-软件生产方式改变" aria-label="Permalink to &quot;第一场变化：软件生产方式改变&quot;">​</a></h3><p>人工智能不再只是程序员写一段代码时使用的补全工具，而会进入需求理解、架构设计、编码、测试、安全检查、部署、运维和持续修改等项目全过程。</p><p>文件因此提出发展智能体驱动的智能编程工具，提升项目级、全流程自主开发能力，并推动智能编程工具与代码托管平台、云服务和开源社区深度适配。这里的政策单位已经不是“一个函数写得快不快”，而是“一个软件项目能否被更高效、更可靠地完成”。</p><p>这也解释了为什么文件同时要求软件企业开展智能化技改。真正的技改不是给每位程序员装一个聊天插件，而是重新设计研发流程、质量控制、安全检查和组织协作方式，并以代码质量、研发效益等实际结果评价成效。</p><h3 id="第二场变化-软件产品形态改变" tabindex="-1">第二场变化：软件产品形态改变 <a class="header-anchor" href="#第二场变化-软件产品形态改变" aria-label="Permalink to &quot;第二场变化：软件产品形态改变&quot;">​</a></h3><p>过去的软件主要等待用户点击菜单、填写表单和发出命令。智能体软件则能够接收目标、理解环境、选择工具、连续执行步骤，并根据结果调整后续行动。</p><p>因此，文件没有只谈“给原有软件增加AI功能”，而是把“智能体软件”作为一种新形态单独部署。它既包括嵌入操作系统、数据库、工业软件和终端的软件能力，也包括能够跨场景工作的通用智能体、垂直行业智能体和工业智能体。</p><p>这相当于把智能体从一个界面功能提升为一种软件产品类别。</p><h3 id="第三场变化-软件服务模式改变" tabindex="-1">第三场变化：软件服务模式改变 <a class="header-anchor" href="#第三场变化-软件服务模式改变" aria-label="Permalink to &quot;第三场变化：软件服务模式改变&quot;">​</a></h3><p>传统软件服务通常围绕许可证、项目实施和售后维护展开。智能软件服务则可能变成一条长期运行的服务链：模型持续更新，知识持续补充，智能体持续执行，权限和成本持续变化，运行结果也需要持续验证。</p><p>所以文件提出打造端到端智能应用服务链，引导软件企业向人工智能应用服务商转型，并从一次性交付转向持续服务与价值交付。</p><p>这三场变化合在一起，才是“人工智能+软件”的完整含义：AI不是软件里的一个按钮，而是在重新组织软件的生产、产品和商业模式。</p><h2 id="三、2028年与2030年-从规模化推广走向产业升级" tabindex="-1">三、2028年与2030年：从规模化推广走向产业升级 <a class="header-anchor" href="#三、2028年与2030年-从规模化推广走向产业升级" aria-label="Permalink to &quot;三、2028年与2030年：从规模化推广走向产业升级&quot;">​</a></h2><p>209号文设定了两个阶段目标。</p><p>到2028年：</p><ul><li>智能编程工具和智能开发平台推广覆盖2万家规模以上软件企业；</li><li>累计组织实施100项软件企业智能化技改项目；</li><li>在重点行业打造100个智能体软件标杆应用；</li><li>建设15家以上软硬件适配中心；</li><li>孵化5个以上优质开源项目。</li></ul><p>到2030年：</p><ul><li>关键软件全面实现智能化升级；</li><li>智能编程、智能体软件和智能服务成为产业新增长极；</li><li>建成若干具有国际影响力的开源社区和产业集群。</li></ul><p>这些数字不能简单相加，因为它们分别对应不同的政策目的。</p><p>“覆盖2万家企业”衡量的是生产工具扩散；“100项技改”要求出现可复用的软件企业改造样板；“100个智能体标杆”衡量的是新产品能否进入真实行业；“15家适配中心”承担的是软硬件协同和产业验证；“5个以上开源项目”则指向公共技术生态。</p><p>换句话说，文件并不是只追求多做一些Agent应用，而是在同时建设采用规模、示范项目、验证设施和开源底座。</p><p>从这两组目标看，2028年侧重规模化推广与应用验证，2030年进一步指向关键软件升级、新业态成长，以及具有国际影响力的开源社区和产业集群建设。它们体现的是从扩大应用走向产业升级的政策路径，并不意味着产业结构届时已经定型。</p><p><img src="'+h+'" alt="图 2｜2028年目标覆盖企业、项目、应用、适配中心与开源生态；2030年进一步指向产业升级。"></p><p><em>图 2：2028年目标覆盖企业、项目、应用、适配中心与开源生态；2030年进一步指向产业升级。 来源：工信部相关政策文件，作者整理。</em></p><h3 id="智能体是新增长点-但209号文并不等于-agent专项政策" tabindex="-1">智能体是新增长点，但209号文并不等于“Agent专项政策” <a class="header-anchor" href="#智能体是新增长点-但209号文并不等于-agent专项政策" aria-label="Permalink to &quot;智能体是新增长点，但209号文并不等于“Agent专项政策”&quot;">​</a></h3><p><a href="https://www.miit.gov.cn/jgsj/xxjsfzs/wjfb/art/2026/art_91a26793271e4c77aca49ecde4472999.html" target="_blank" rel="noreferrer">《实施方案》</a>同时部署了基础软件和工业软件本身的智能化升级：操作系统、数据库要改进智能体调度、性能调优、运维与安全，并联合芯片、服务器厂商开展软硬件适配，建设适配中心；CAD、CAE、EDA等工业软件要将AI用于制图、设计和仿真，工业互联网平台也要提升数据分析、生产调度和多智能体协同决策能力。</p><p>因此，理解209号文，需要把存量软件升级与新型软件培育放在一起看。传统基础软件要智能化，工业软件要智能化，开发方式也要智能化；智能体是其中值得重视的新软件形态，但不能代替整份文件的软件产业转型议题。</p><h2 id="四、最重要的新概念不是-智能编程-而是-智能体软件" tabindex="-1">四、最重要的新概念不是“智能编程”，而是“智能体软件” <a class="header-anchor" href="#四、最重要的新概念不是-智能编程-而是-智能体软件" aria-label="Permalink to &quot;四、最重要的新概念不是“智能编程”，而是“智能体软件”&quot;">​</a></h2><p>智能编程当然重要，它直接影响软件供给效率，也最容易在短期内形成规模。但从产业结构看，209号文最值得注意的是第四部分：<strong>培育智能体软件新业态，加速推动持续进化。</strong></p><p>这里至少出现了四个层次。</p><h3 id="_1-智能体运行框架" tabindex="-1">1. 智能体运行框架 <a class="header-anchor" href="#_1-智能体运行框架" aria-label="Permalink to &quot;1. 智能体运行框架&quot;">​</a></h3><p>文件要求加强智能体运行框架等工程化技术研究，提高复杂任务可靠执行和多智能体协同作业能力。</p><p>“运行框架”说明政策开始关注模型之外的工程基础。<strong>从企业级工程落地看</strong>，大模型可以生成一次回答，却不会自动解决长期任务中的状态保存、工具调用、权限约束、失败恢复、并发冲突、协作交接和结果验收。这些并非文件逐项规定的功能清单，而是本文从可靠执行与多智能体协同要求进一步推导出的工程问题。</p><h3 id="_2-智能体软件开发平台" tabindex="-1">2. 智能体软件开发平台 <a class="header-anchor" href="#_2-智能体软件开发平台" aria-label="Permalink to &quot;2. 智能体软件开发平台&quot;">​</a></h3><p>文件提出建设智能体软件开发平台，并完善研发、测试、部署和运维工具链。</p><p>这意味着Agent开发不能长期停留在提示词、演示页面和临时脚本阶段。它需要像成熟软件一样被设计、测试、发布、监测、升级和维护，也需要有可重复的工程流程。</p><h3 id="_3-智能体软件产品" tabindex="-1">3. 智能体软件产品 <a class="header-anchor" href="#_3-智能体软件产品" aria-label="Permalink to &quot;3. 智能体软件产品&quot;">​</a></h3><p>文件分别部署通用智能体、终端智能体、垂直领域专业智能体和工业智能体。不同类别对应不同的可靠性与责任要求。</p><p>办公信息处理Agent可以在人的复核下工作；终端Agent需要轻量推理和隐私保护；垂直行业Agent需要知识图谱与行业数据；工业智能体则要进入核心生产环节，与工业控制系统和企业核心业务系统交互，因此必须更加安全可靠、行为可校验。</p><h3 id="_4-智能体软件应用市场" tabindex="-1">4. 智能体软件应用市场 <a class="header-anchor" href="#_4-智能体软件应用市场" aria-label="Permalink to &quot;4. 智能体软件应用市场&quot;">​</a></h3><p>文件进一步提出建设智能体软件应用商店和技能包资源库，并规范上架审核与运营管理。</p><p>这一步非常关键。只有当智能体、技能和组件能够被发现、安装、组合、更新和交易，Agent才可能形成真正的软件生态，而不是每个项目都从头定制。</p><p>这四层组合起来，构成了一条完整产业链：</p><blockquote><p>运行框架提供底座，开发平台生产软件，智能体产品进入场景，应用市场完成分发，服务商负责交付与运营。</p></blockquote><p><img src="'+d+'" alt="图 3｜运行框架、开发平台、智能体产品与分发市场形成产业关系，交付和治理贯穿其中。"></p><p><em>图 3：运行框架、开发平台、智能体产品与分发市场形成产业关系，交付和治理贯穿其中。 来源：工信部相关政策文件，作者整理。</em></p><h2 id="五、skills被正式纳入智能体软件应用市场-意义不在-提示词市场" tabindex="-1">五、Skills被正式纳入智能体软件应用市场，意义不在“提示词市场” <a class="header-anchor" href="#五、skills被正式纳入智能体软件应用市场-意义不在-提示词市场" aria-label="Permalink to &quot;五、Skills被正式纳入智能体软件应用市场，意义不在“提示词市场”&quot;">​</a></h2><p>209号文明确提出建设技能包（Skills）资源库，引导创新主体开发高质量专业技能包、知识库和面向智能体的功能组件。</p><p>表面上看，Skill只是把一项能力打包，例如整理合同、分析设备故障、生成报价或者操作某个业务系统。但一旦技能进入企业和应用市场，它就不能只是几段提示词。</p><p><strong>从企业级工程落地看</strong>，一个可产业化的技能包至少会涉及以下问题。这并非文件逐项规定的要求，而是本文从技能包资源库、上架审核与运营管理等部署进一步推导出的工程问题：</p><ul><li>它由谁发布，身份是否可信；</li><li>它适用于什么智能体和运行环境；</li><li>它依赖哪些模型、数据和工具；</li><li>它可以获得什么权限；</li><li>它的版本怎样升级和回退；</li><li>执行过程中产生了什么外部效果；</li><li>出错以后能否停止、恢复或撤销；</li><li>谁审核它能够上架，谁负责持续运营；</li><li>它的知识产权、数据来源和安全风险是否清楚。</li></ul><p>因此，真正的Skills市场不会只是“提示词商店”。它更接近智能体时代的软件包生态：能力被模块化封装，依赖和权限被显式描述，运行效果能够检查，版本与责任能够追踪。</p><p>这也会产生新的产业分工。有人开发通用技能，有人提供行业知识包，有人建设企业内部技能库，有人负责安全审查和兼容测试，还有人运营面向特定行业的智能体市场。</p><p>未来大量小型AI企业未必需要训练自己的大模型，但可以围绕一个高价值业务环节，把知识、工具与流程封装成专业技能包。这与创业支持计划中强调的智能体开发者、开源贡献者和轻量化专业主体形成了直接连接。</p><h2 id="六、-行为可校验-为什么可能成为工业智能体的分水岭" tabindex="-1">六、“行为可校验”为什么可能成为工业智能体的分水岭 <a class="header-anchor" href="#六、-行为可校验-为什么可能成为工业智能体的分水岭" aria-label="Permalink to &quot;六、“行为可校验”为什么可能成为工业智能体的分水岭&quot;">​</a></h2><p>在有关工业智能体的部署中，文件特别提出“安全可靠、行为可校验”。</p><p>这四个字很容易被略过，却可能决定智能体能否真正进入生产经营流程。</p><p>一个聊天机器人说错一句话，通常可以由用户忽略或纠正；一个工业智能体如果修改排产、调用设备、调整参数、写入业务系统或者触发采购，错误就可能变成真实损失。此时，仅仅保存聊天记录并不能证明它做了什么，也不能证明结果是否符合授权。</p><p><strong>从企业级工程落地看</strong>，本文将“行为可校验”进一步拆成以下问题；这是工程分析框架，并非文件逐项列出的验收标准：</p><ul><li>智能体接到了什么任务；</li><li>谁授权它执行；</li><li>它调用了什么工具；</li><li>工具实际产生了什么效果；</li><li>执行结果是否满足业务目标；</li><li>谁拥有验收和裁决权；</li><li>失败后的恢复是否重复了未知副作用。</li></ul><p>这些问题无法只靠模型“自我说明”解决。模型输出可以成为证据的一部分，却不能自动成为事实；程序可以检查文件、状态、哈希和调用结果，却不能擅自替代业务责任人作出语义裁决。</p><p>因此，工业智能体需要的不只是更高的模型准确率，还需要任务合同、身份与授权、执行记录、效果证据、独立验证和可恢复机制。谁能把这套工程能力做成低成本、可集成的基础设施，谁才有可能跨过从“能演示”到“敢使用”的门槛。</p><p><img src="'+c+'" alt="图 4｜行为可校验需要区分任务、授权、执行、效果与验收；恢复前还要核对状态和副作用。"></p><p><em>图 4：行为可校验需要区分任务、授权、执行、效果与验收；恢复前还要核对状态和副作用。 来源：工信部相关政策文件，作者整理。</em></p><h2 id="七、文件正在给智能体标准化划出四条主线" tabindex="-1">七、文件正在给智能体标准化划出四条主线 <a class="header-anchor" href="#七、文件正在给智能体标准化划出四条主线" aria-label="Permalink to &quot;七、文件正在给智能体标准化划出四条主线&quot;">​</a></h2><p>209号文并没有宣布一套已经完成的智能体国家标准，而是明确部署后续标准研制。这个区别非常重要。</p><p>文件提出：</p><ul><li>制定智能编程能力成熟度分级评估标准；</li><li>研制面向软硬协同的智能体接口标准；</li><li>研究“模型即服务”和“智能体即服务”等智能服务标准；</li><li>研究智能体身份标识、可信互联、数据安全和行为管控技术；</li><li>推动建立覆盖开发、部署、应用环节的智能体安全管理规范。</li></ul><p>由此可以看出，未来标准化工作很可能沿着四条主线展开。</p><p>第一条是<strong>能力标准</strong>：智能编程工具和开发平台究竟能完成多大范围的任务，成熟度怎样分级，不能只靠厂商宣传。</p><p>第二条是<strong>接口标准</strong>：不同模型、终端、硬件、软件系统和智能体怎样连接，避免所有能力都被锁在单一平台中。</p><p>第三条是<strong>服务标准</strong>：MaaS和AaaS怎样定义服务范围、质量、计量、责任与持续运营要求。</p><p>第四条是<strong>治理标准</strong>：智能体以什么身份进入系统，怎样获得权限，如何可信互联，数据怎样保护，行为怎样记录和管控。</p><p>这也意味着，目前正处在“方向已经明确、标准尚在形成”的窗口期。企业现在最有价值的工作，不是抢先宣称自己符合尚未发布的国家标准，而是积累真实运行证据、接口实践、安全机制和失败案例，为后续标准研制和试点验证提供可检查的工程材料。</p><h2 id="八、开源不再只是开发方式-而是产业发现、验证和扩散机制" tabindex="-1">八、开源不再只是开发方式，而是产业发现、验证和扩散机制 <a class="header-anchor" href="#八、开源不再只是开发方式-而是产业发现、验证和扩散机制" aria-label="Permalink to &quot;八、开源不再只是开发方式，而是产业发现、验证和扩散机制&quot;">​</a></h2><p>文件把开源协同创新列入软件智能化发展的基础建设，并提出依托全国性开源基金会和人工智能开源社区，引导企业开放智能编程、软件产品智能化和智能体成果；支持重点项目在社区首发；加强自主开源许可协议应用与合规指引；建立优质开源项目遴选和培育机制。</p><p>更值得关注的是，文件提出探索把开源贡献作为发现软件领域优质中小企业的重要参考指标。</p><p>这与创业支持计划中利用开源项目星标数等公开指标主动识别高成长潜力企业相互呼应，但209号文又向前走了一步：不仅用开源数据发现企业，还要把优质开源项目送进制造、金融等真实行业应用。</p><p>这会改变Agent基础设施项目的成长路径。</p><p>过去，一个开源项目可能首先被看作技术社区成果；未来，它还可能成为政策培育、产业验证、服务商合作和场景落地的入口。但前提是开源项目必须从“代码可见”走向“能力可用”：安装文档清楚、接口稳定、版本可追踪、许可证合规、测试可以复现，并且具有真实使用证据。</p><p>Star能够提高可见度，却不能替代可靠性；发布了代码，也不等于形成产业能力。政策真正需要孵化的，是能够进入真实软件生产和行业应用的优质项目。</p><h2 id="九、钱、项目和场景会从哪里来-文件已经给出方向-但尚未形成统一申报入口" tabindex="-1">九、钱、项目和场景会从哪里来：文件已经给出方向，但尚未形成统一申报入口 <a class="header-anchor" href="#九、钱、项目和场景会从哪里来-文件已经给出方向-但尚未形成统一申报入口" aria-label="Permalink to &quot;九、钱、项目和场景会从哪里来：文件已经给出方向，但尚未形成统一申报入口&quot;">​</a></h2><p>209号文在组织保障中提出，通过“揭榜挂帅”等机制推动重点任务落地，统筹资金渠道和首版次软件产品认定政策，对符合条件的项目给予支持，并利用财政专项资金加快关键技术研发、基础设施建设和场景应用。</p><p>这说明政策不只是表达方向，后续存在形成项目、试点、标准、适配中心、标杆应用和地方支持措施的现实可能。</p><p>值得注意的是，《实施方案》在算力服务支撑条款中已经提出，用好<strong>算力券等普惠性支持政策</strong>，降低软件企业算力使用成本。<a href="https://www.miit.gov.cn/jgsj/xxjsfzs/gzdt/art/2026/art_45df9463e105446c996568f299e07bca.html" target="_blank" rel="noreferrer">工信部官方解读</a>进一步明确：鼓励各地用好“算力券”等政策，对采购自主编程工具、调用自主大模型编程服务的费用按一定比例给予支持。这说明政策支持不只面向重大项目，也为企业采购智能编程工具、使用模型服务的普惠型支持提供了具体方向。</p><p>但必须区分政策方向与已经获得的权益。</p><p>方案及上述解读没有规定全国统一的补贴比例、申领条件和执行时间，也没有公布统一的项目申报时间、企业资格、评分细则、资金规模和单个项目支持金额。“支持”“鼓励”“探索”不等于所有相关企业都能自动获得补贴。具体能否申请、支持哪些费用、何时兑现，仍需以各地政策和申报通知为准。</p><p>企业现阶段最应该准备的不是一份泛泛的AI介绍，而是五类材料：</p><ol><li>可复现的产品能力与技术边界；</li><li>真实客户场景与效果证据；</li><li>研发、测试、部署、运维的完整流程；</li><li>数据、权限、安全和知识产权说明；</li><li>可复制、可推广、可由第三方检查的示范案例。</li></ol><p>等到项目征集开始时，真正具有竞争力的不会是最会使用政策词汇的团队，而是已经能够证明自己解决了文件所指出的工程问题的团队。</p><h2 id="十、这份文件将催生怎样的新软件产业链" tabindex="-1">十、这份文件将催生怎样的新软件产业链 <a class="header-anchor" href="#十、这份文件将催生怎样的新软件产业链" aria-label="Permalink to &quot;十、这份文件将催生怎样的新软件产业链&quot;">​</a></h2><p>209号文覆盖的角色远多于大模型公司。沿着文件部署，可以看到一条正在形成的新产业链：</p><p><img src="'+g+'" alt="智能体软件产业链的八类专业分工及其核心竞争力。"></p><p><em>图 5：智能体软件产业链的八类专业分工及其核心竞争力。 来源：作者依据209号文整理。</em></p><p>这张图也说明，未来并不是所有公司都要做“大而全的Agent平台”。围绕运行、技能、评测、安全、集成或某个垂直行业形成专业能力，同样可能成为独立业务。</p><p>对于中小企业来说，这尤其重要。它们很难与大厂竞争通用基础模型，却可以在一个窄而深的场景中形成数据、流程、知识和交付优势。一个能够稳定完成采购询价、设备故障分析、研发资料整理、质量追踪或者外贸客户管理的智能体，可能比一个功能繁多却无法进入实际业务的通用助手更有商业价值。</p><h2 id="十一、对软件企业的真正影响-竞争指标将从-有没有ai-变成-ai产生了什么效果" tabindex="-1">十一、对软件企业的真正影响：竞争指标将从“有没有AI”变成“AI产生了什么效果” <a class="header-anchor" href="#十一、对软件企业的真正影响-竞争指标将从-有没有ai-变成-ai产生了什么效果" aria-label="Permalink to &quot;十一、对软件企业的真正影响：竞争指标将从“有没有AI”变成“AI产生了什么效果”&quot;">​</a></h2><p>文件在软件企业智能化技改部分提出，把代码质量、研发效益等智能编程应用实效作为重要依据。这句话会对软件公司的AI采用方式产生直接影响。</p><p>未来，“我们已经接入某个大模型”很可能不再是一项有说服力的成果。企业需要回答：</p><ul><li>交付周期缩短了多少；</li><li>缺陷率是否下降；</li><li>安全问题能否更早发现；</li><li>测试覆盖和维护效率是否提高；</li><li>复杂项目是否能够被连续完成；</li><li>模型或工具变化以后，流程是否仍能稳定运行；</li><li>人员岗位怎样调整，而不是简单被替代。</li></ul><h3 id="一个容易被忽略的政策信号-稳岗、扩岗、转岗" tabindex="-1">一个容易被忽略的政策信号：“稳岗、扩岗、转岗” <a class="header-anchor" href="#一个容易被忽略的政策信号-稳岗、扩岗、转岗" aria-label="Permalink to &quot;一个容易被忽略的政策信号：“稳岗、扩岗、转岗”&quot;">​</a></h3><p><a href="https://www.miit.gov.cn/jgsj/xxjsfzs/gzdt/art/2026/art_45df9463e105446c996568f299e07bca.html" target="_blank" rel="noreferrer">工信部官方解读</a>对就业的表述非常直接，明确从**“稳岗、扩岗、转岗”**三个方面考虑：</p><ul><li><strong>稳岗</strong>：稳定软件从业者的存量岗位，防止“大规模突发性失业潮”。</li><li><strong>扩岗</strong>：以智能体软件、智能服务等新业态拓展就业空间，满足代码审查、AI安全等新岗位需求。</li><li><strong>转岗</strong>：加强岗位培训，推动软件从业人员向高附加值岗位转型。</li></ul><p>这让209号文不只涉及技术和产品，也直接回应了一个现实问题：<strong>AI改造软件产业以后，人怎么办。</strong> 政策并不是简单鼓励“AI替代程序员”，而是在推动生产组织重构的同时，把岗位改造、技能培训、新岗位开发和就业影响评估一起纳入政策框架。</p><p>从企业实施角度看，智能化技改方案除了计算研发效率和工具成本，还应说明哪些岗位会改变、人员如何培训和转岗、代码审查与AI安全等职责由谁承担，以及如何识别和应对就业风险。减少了多少人工操作，不能单独成为转型成效的完整说明。</p><p>真正成熟的软件智能化，不是把责任交给模型，而是重新安排人与智能体的分工：机器承担大量可执行工作，人负责目标、边界、专业判断、异常处置与最终责任。</p><h2 id="十二、不同类型的软件企业-应该怎样对照转型" tabindex="-1">十二、不同类型的软件企业，应该怎样对照转型 <a class="header-anchor" href="#十二、不同类型的软件企业-应该怎样对照转型" aria-label="Permalink to &quot;十二、不同类型的软件企业，应该怎样对照转型&quot;">​</a></h2><p>209号文对软件企业提出的，不是一个统一的“接入大模型”任务。不同企业拥有的客户、产品、技术和交付方式不同，转型起点也应不同。判断顺序应当是：<strong>先看现有业务中什么值得保留，再看哪个环节适合交给智能体，最后决定需要补齐什么能力。</strong></p><h3 id="_1-传统软件厂商-保留业务底座-逐步增加可以承担任务的产品能力" tabindex="-1">1. 传统软件厂商：保留业务底座，逐步增加可以承担任务的产品能力 <a class="header-anchor" href="#_1-传统软件厂商-保留业务底座-逐步增加可以承担任务的产品能力" aria-label="Permalink to &quot;1. 传统软件厂商：保留业务底座，逐步增加可以承担任务的产品能力&quot;">​</a></h3><p>对于已经拥有ERP、CRM、财务、协同办公或行业软件的企业，最有价值的资产往往是业务对象、权限体系、历史数据和客户信任。这些资产不应因为出现了自然语言界面就被推倒重建。</p><p>更可行的路径，是先让智能体完成边界清楚的任务，例如识别异常订单、整理客户跟进建议、解释经营数据或生成待审核的业务单据。智能体通过受控接口使用原有系统，而不是绕过权限直接修改数据库。</p><p>转型的关键，不是把菜单换成聊天框，而是把“用户逐步操作”变成“用户提出目标，系统在授权范围内完成任务”。涉及付款、合同、库存和客户承诺等重要动作时，原有的审批与责任机制仍需保留。</p><h3 id="_2-项目交付与集成服务商-从一次性交付-走向可复制产品与持续运营" tabindex="-1">2. 项目交付与集成服务商：从一次性交付，走向可复制产品与持续运营 <a class="header-anchor" href="#_2-项目交付与集成服务商-从一次性交付-走向可复制产品与持续运营" aria-label="Permalink to &quot;2. 项目交付与集成服务商：从一次性交付，走向可复制产品与持续运营&quot;">​</a></h3><p>这类企业熟悉客户现场、业务流程和系统集成，优势不在于重新训练一个基础模型，而在于知道客户真正需要解决什么问题。</p><p>转型应从已有项目中寻找重复出现的需求，把可以复用的知识、接口、技能和验收方法沉淀为产品包，明确哪些部分标准交付、哪些部分仍需定制。与此同时，要把模型更新、知识维护、故障处理、安全检查和效果复核纳入持续服务。</p><p>商业模式也需要随之调整：实施费、订阅费或运营服务费分别覆盖什么，客户提供哪些数据，谁负责异常处置，服务结束后如何交接，都应写清楚。可以探索与效果相关的收费，但前提是效果能够计量、责任能够归因，而不是先承诺“结果付费”再寻找验收办法。</p><h3 id="_3-开发工具与平台企业-从单点生成能力-走向可检验的工程能力" tabindex="-1">3. 开发工具与平台企业：从单点生成能力，走向可检验的工程能力 <a class="header-anchor" href="#_3-开发工具与平台企业-从单点生成能力-走向可检验的工程能力" aria-label="Permalink to &quot;3. 开发工具与平台企业：从单点生成能力，走向可检验的工程能力&quot;">​</a></h3><p>对于代码工具、开发平台、云服务和运行框架企业，竞争重点会从“生成了一段代码”转向“一个项目能否稳定推进并形成可维护成果”。</p><p>企业需要围绕自己的产品边界，补齐或接入版本管理、测试、安全检查、部署、状态保存、工具权限、成本控制和异常恢复能力。并不是每个平台都要自行建设全部环节，但必须说明依赖谁、怎样连接、失败时由谁处理。</p><p>评价也应回到真实项目：交付周期、缺陷返工、维护成本和人工介入是否改善。单次演示和模型跑分，可以说明部分能力，却不能替代项目级交付证据。</p><h3 id="_4-行业中小软件企业-围绕一个高价值环节-把专业知识做深" tabindex="-1">4. 行业中小软件企业：围绕一个高价值环节，把专业知识做深 <a class="header-anchor" href="#_4-行业中小软件企业-围绕一个高价值环节-把专业知识做深" aria-label="Permalink to &quot;4. 行业中小软件企业：围绕一个高价值环节，把专业知识做深&quot;">​</a></h3><p>中小企业不必把“大而全的Agent平台”当成转型的默认终点。更现实的机会，往往在采购询价、设备故障分析、质量追踪、研发资料整理等窄而深的业务环节。</p><p>这类企业可以利用现有模型和运行平台，把行业知识、工具接口与处理流程做成专业智能体或Skills。但真正能够销售的，不只是提示词，而是明确的适用范围、数据要求、权限边界、测试样例、升级方式和服务承诺。</p><p>是否值得产品化，要看同一套能力能否在多个客户中复用，以及部署与维护成本是否可控。如果每个客户都需要重新开发大量逻辑，就仍然需要按项目业务核算，不能仅凭使用了Agent便假定已经形成软件产品。</p><p>四类企业的转型方向可以归纳为：</p><p><img src="'+u+'" alt="图 6｜不同软件企业应从已有优势和业务边界出发，选择转型入口并补齐能力。"></p><p><em>图 6：不同软件企业应从已有优势和业务边界出发，选择转型入口并补齐能力。 来源：作者依据209号文所作的企业转型分析。</em></p><p>这是一种基于政策方向的经营分析，不是文件规定的企业分类或统一转型路线。企业也可能同时处在其中几类位置。重要的是找到可以形成价值的业务边界，而不是为了对应政策术语，把现有产品全部重新命名。</p><h2 id="十三、企业转型怎样落地-从一个场景到持续交付" tabindex="-1">十三、企业转型怎样落地：从一个场景到持续交付 <a class="header-anchor" href="#十三、企业转型怎样落地-从一个场景到持续交付" aria-label="Permalink to &quot;十三、企业转型怎样落地：从一个场景到持续交付&quot;">​</a></h2><p>明确方向以后，企业仍然需要回答一个实际问题：第一步做什么，做到什么程度才值得继续投入？</p><p>转型不宜先从全面换系统、集中采购模型或设立庞大的AI部门开始。更稳妥的做法，是选择一个可验证的业务任务，逐步完成“选场景、做试点、形成服务、扩大复用”的过程。下面是一条实施建议，不是209号文规定的项目流程或时间表。</p><h3 id="第一步-选择场景-同时建立改造前的业务基线" tabindex="-1">第一步：选择场景，同时建立改造前的业务基线 <a class="header-anchor" href="#第一步-选择场景-同时建立改造前的业务基线" aria-label="Permalink to &quot;第一步：选择场景，同时建立改造前的业务基线&quot;">​</a></h3><p>优先选择需求真实、重复发生、输入较稳定、结果能够检查的任务。还要确认企业有权使用相关数据，有权限接入必要系统，并能在出错时由人工接管。</p><p>例如，可以先做采购询价整理和异常提示，再考虑自动生成待审批单据；不应从没有明确授权边界的自动付款开始。</p><p>试点前就应记录原有流程的耗时、处理量、错误与返工情况、人工成本和验收方式，并明确业务负责人。否则，即使试点完成，也很难判断改善来自AI、流程调整，还是额外投入了更多人工。</p><h3 id="第二步-在受控范围内试点-把效果与失败一起记录" tabindex="-1">第二步：在受控范围内试点，把效果与失败一起记录 <a class="header-anchor" href="#第二步-在受控范围内试点-把效果与失败一起记录" aria-label="Permalink to &quot;第二步：在受控范围内试点，把效果与失败一起记录&quot;">​</a></h3><p>先约定允许使用的数据、可以调用的工具、不得越过的权限，以及人工介入条件，再让智能体进入实际流程。可以从只读、生成建议或人审后执行开始，根据证据逐步扩大范围。</p><p>验证不能只看成功案例。还应观察数据缺失、工具超时、权限失效、模型变化和重复请求时，系统是否能够停止、提示、转交人工或安全恢复。产生外部效果的操作尤其需要检查，不能把“没有收到成功响应”直接当成“没有执行”。</p><p>只有在预先约定的验收方法下，质量、效率和可控性达到要求，才进入下一步；达不到要求，就收窄场景、调整方案或停止试点。</p><h3 id="第三步-形成能够长期承担的服务-重新安排岗位与成本" tabindex="-1">第三步：形成能够长期承担的服务，重新安排岗位与成本 <a class="header-anchor" href="#第三步-形成能够长期承担的服务-重新安排岗位与成本" aria-label="Permalink to &quot;第三步：形成能够长期承担的服务，重新安排岗位与成本&quot;">​</a></h3><p>技术试点通过，不等于已经具备商业交付条件。企业还需要明确模型与知识的更新责任、异常处理人、权限变更流程、版本回退方式，以及客户如何提出异议和完成验收。</p><p>人员分工也应随之调整。业务人员负责目标和验收，工程人员负责接口、运行与恢复，安全人员参与重要权限和数据边界审查。具体岗位可以由同一人兼任，但关键授权与验收不能因为“由AI处理”而无人负责。培训、必要的独立复核和岗位调整成本，也应计入转型投入。</p><p>同时要算清完整成本：模型调用与算力只是其中一部分，数据整理、系统集成、人工复核、监测、故障处理、升级维护和售后同样需要支付。只有把这些成本与可计量的客户收益放在一起，才能判断订阅、实施费或运营服务费是否可持续。</p><h3 id="第四步-证据支持以后-再扩大到更多客户和场景" tabindex="-1">第四步：证据支持以后，再扩大到更多客户和场景 <a class="header-anchor" href="#第四步-证据支持以后-再扩大到更多客户和场景" aria-label="Permalink to &quot;第四步：证据支持以后，再扩大到更多客户和场景&quot;">​</a></h3><p>扩张之前，要区分哪些能力可以共用，哪些配置依赖行业或客户，哪些权限必须逐一授权。标准安装包、技能版本、兼容性说明、测试样例、服务文档和回退方案，应成为交付的一部分。</p><p>同一套智能体在一个客户处有效，并不意味着换一套数据、一个模型或一个业务系统仍然有效。新增客户和环境需要重新验证关键假设，避免把首个案例的成功当成普遍结论。</p><p>扩大投入的依据，应是可复用程度、客户收益、服务成本和风险是否共同成立。如果长期依赖大量人工兜底、收益不足以覆盖成本，或重要副作用仍无法查清，就不应为了追赶政策窗口而勉强规模化。</p><p>因此，软件企业转型的核心不是“用了多少AI”，而是三个问题：<strong>客户是否得到可验证的改善，企业是否形成可持续的交付能力，人的责任与风险边界是否仍然清楚。</strong></p><p><img src="'+b+'" alt="图 7｜先建立基线，再做受控试点；持续服务和扩大复用，都必须由证据支持。"></p><p><em>图 7：先建立基线，再做受控试点；持续服务和扩大复用，都必须由证据支持。 来源：作者依据209号文所作的企业转型分析。</em></p><h2 id="十四、五个最容易出现的误读" tabindex="-1">十四、五个最容易出现的误读 <a class="header-anchor" href="#十四、五个最容易出现的误读" aria-label="Permalink to &quot;十四、五个最容易出现的误读&quot;">​</a></h2><h3 id="误读一-国家要补贴所有ai软件公司" tabindex="-1">误读一：国家要补贴所有AI软件公司 <a class="header-anchor" href="#误读一-国家要补贴所有ai软件公司" aria-label="Permalink to &quot;误读一：国家要补贴所有AI软件公司&quot;">​</a></h3><p>文件提出统筹资金、首版次政策和财政专项资金，但没有给出普遍补贴权利。具体支持仍取决于后续项目和地方细则。</p><h3 id="误读二-接入大模型就完成了软件智能化" tabindex="-1">误读二：接入大模型就完成了软件智能化 <a class="header-anchor" href="#误读二-接入大模型就完成了软件智能化" aria-label="Permalink to &quot;误读二：接入大模型就完成了软件智能化&quot;">​</a></h3><p>政策评价的是研发效益、代码质量、产品升级、服务价值和真实应用。调用模型只是投入，不是结果。</p><h3 id="误读三-智能体就是一个聊天界面" tabindex="-1">误读三：智能体就是一个聊天界面 <a class="header-anchor" href="#误读三-智能体就是一个聊天界面" aria-label="Permalink to &quot;误读三：智能体就是一个聊天界面&quot;">​</a></h3><p>文件同时部署运行框架、复杂任务执行、多智能体协同、研发运维工具链、系统集成和行为校验，明显超出了聊天机器人的范围。</p><h3 id="误读四-skills市场就是卖提示词" tabindex="-1">误读四：Skills市场就是卖提示词 <a class="header-anchor" href="#误读四-skills市场就是卖提示词" aria-label="Permalink to &quot;误读四：Skills市场就是卖提示词&quot;">​</a></h3><p>企业级技能需要版本、接口、依赖、权限、安全、审核和持续运营。没有这些条件，技能很难进入核心业务系统。</p><h3 id="误读五-政策已经给出了统一智能体标准" tabindex="-1">误读五：政策已经给出了统一智能体标准 <a class="header-anchor" href="#误读五-政策已经给出了统一智能体标准" aria-label="Permalink to &quot;误读五：政策已经给出了统一智能体标准&quot;">​</a></h3><p>文件只是启动和推进相关标准研制。当前尚不能把企业自定义概念包装成国家标准，更不能提前宣称认证通过。</p><h2 id="十五、真正的机会-软件不再只是一套工具-而可能成为持续工作的组织能力" tabindex="-1">十五、真正的机会：软件不再只是一套工具，而可能成为持续工作的组织能力 <a class="header-anchor" href="#十五、真正的机会-软件不再只是一套工具-而可能成为持续工作的组织能力" aria-label="Permalink to &quot;十五、真正的机会：软件不再只是一套工具，而可能成为持续工作的组织能力&quot;">​</a></h2><p>过去的软件帮助人记录信息、执行命令和管理流程。生成式AI出现以后，软件开始理解自然语言；智能体进一步出现以后，软件开始接收目标、调用工具并连续完成任务。</p><p>当这种能力进入企业，软件购买逻辑也会发生变化。</p><p>企业购买的可能不再只是一个系统账号，而是一项可以持续交付结果的数字能力；不再只是安装某套功能，而是让采购、研发、销售、客服、合规或运营环节多出一个能够工作的智能角色。</p><p>这也是209号文为什么同时讨论软件生产、智能体产品、智能服务和就业组织。它所面对的不是一个孤立技术升级，而是软件、服务与劳动组织方式之间的重新组合。</p><p>模型提供智能，却不能自动形成岗位；工具提供动作，却不能自动形成责任；工作流提供路径，却不能替代业务判断。真正的数字员工系统，需要把模型、工具、技能、身份、职责、授权、协作、验证和恢复组织成一个长期可运行的整体。</p><p>从这个角度看，209号文打开的并不只是“AI写软件”的市场。</p><p>它还打开了“软件成为智能体、智能体进入组织、组织重新配置生产能力”的市场。</p><h2 id="结语-从模型、交付和创业-走向-智能体软件产业" tabindex="-1">结语：从模型、交付和创业，走向“智能体软件产业” <a class="header-anchor" href="#结语-从模型、交付和创业-走向-智能体软件产业" aria-label="Permalink to &quot;结语：从模型、交付和创业，走向“智能体软件产业”&quot;">​</a></h2><p>2025年，<a href="https://www.mee.gov.cn/zcwj/gwywj/202508/t20250827_1126207.shtml" target="_blank" rel="noreferrer">国务院《关于深入实施“人工智能+”行动的意见》</a>确定了人工智能向经济社会各领域深度融合的国家方向。</p><p>进入2026年以后，政策开始一层一层进入施工阶段。</p><p>414号文组织应用服务商，解决谁来交付；创业支持计划培育AI中小企业，解决谁来创新；209号文则进一步改造软件产业自身，回答未来的软件怎样被生产、怎样持续运行、怎样形成产品与市场，以及怎样被验证和治理。</p><p>从414号文、创业支持计划到209号文，可以看到政策关注点正在从模型能力进一步延伸到应用交付、创业主体、软件产品、持续服务与产业基础设施。</p><p>对软件企业而言，值得把握的是这条政策路径：升级已有软件和开发方式，培育智能体产品与专业Skills，并把持续运营、行为校验和人员转型纳入交付能力。相关机会能否形成真实业务，仍要由产品、客户和运行结果验证。</p><p>209号文由此把问题推进了一步：</p><blockquote><p>当智能体真正成为软件以后，中国准备怎样把它建成一个产业？</p></blockquote><hr><h2 id="主要资料" tabindex="-1">主要资料 <a class="header-anchor" href="#主要资料" aria-label="Permalink to &quot;主要资料&quot;">​</a></h2><ol><li>工业和信息化部：<a href="https://www.miit.gov.cn/jgsj/xxjsfzs/wjfb/art/2026/art_91a26793271e4c77aca49ecde4472999.html" target="_blank" rel="noreferrer">《关于印发〈“人工智能+软件”专项行动实施方案〉的通知》</a>，工信部信发〔2026〕209号，2026年9月11日发布。</li><li>工业和信息化部办公厅：<a href="https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_331b6f1d28ad410aa9df711acf42dbfe.html" target="_blank" rel="noreferrer">《关于开展人工智能应用服务商培育专项行动的通知》</a>，工信厅科函〔2026〕414号，2026年8月31日发布。</li><li>工业和信息化部办公厅：<a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">《人工智能中小企业创业支持计划（2026—2028年）》</a>，工信厅企业〔2026〕31号，2026年9月4日发布。</li><li>国务院：<a href="https://www.mee.gov.cn/zcwj/gwywj/202508/t20250827_1126207.shtml" target="_blank" rel="noreferrer">《关于深入实施“人工智能+”行动的意见》</a>，国发〔2025〕11号。</li><li>数字员工工场：<a href="https://joinwell52-ai.github.io/joinwell52/zh/industry/2026-09-04-miit-414-ai-application-delivery" target="_blank" rel="noreferrer">《工信部414号文深度解读：从模型供给走向应用交付》</a>。</li><li>数字员工工场：<a href="https://joinwell52-ai.github.io/joinwell52/zh/industry/2026-09-08-miit-ai-sme-support-plan" target="_blank" rel="noreferrer">《工信部〈人工智能中小企业创业支持计划〉深度解读：AI创业生态正在形成》</a>。</li><li>工业和信息化部信息技术发展司：<a href="https://www.miit.gov.cn/jgsj/xxjsfzs/gzdt/art/2026/art_45df9463e105446c996568f299e07bca.html" target="_blank" rel="noreferrer">《七问+一图，读懂〈“人工智能+软件”专项行动实施方案〉》</a>，2026年9月11日发布，重点参见第三问与第六问。</li></ol>',206))])}const y=l(f,[["render",m]]);export{x as __pageData,y as default};
